#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    #pragma omp parallel
    {
        std::array<size_t, 4> local = {0, 0, 0, 0};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Treat points on axes as belonging to the "positive" side (>= 0).
            int q = -1;
            if (x >= 0.0 && y >= 0.0) q = 0;          // (+,+)
            else if (x < 0.0 && y >= 0.0) q = 1;      // (-,+)
            else if (x < 0.0 && y < 0.0) q = 2;       // (-,-)
            else /* x >= 0.0 && y < 0.0 */ q = 3;     // (+,-)

            ++local[static_cast<std::size_t>(q)];
        }

        #pragma omp critical
        {
            bins[0] += local[0];
            bins[1] += local[1];
            bins[2] += local[2];
            bins[3] += local[3];
        }
    }
}
